@Override
public FileOrcStatistics call() throws IOException {
    Path path = new Path(file.toUri());
    Reader reader = OrcFile.createReader(path, // PATH: Test should invoke the next OrcConf.getLong(...) [step in execution path]
    OrcFile.readerOptions(hadoopConf).maxLength(OrcConf.MAX_FILE_LENGTH.getLong(hadoopConf)));
    ColumnStatistics[] statistics = reader.getStatistics();
    TypeDescription schema = reader.getSchema();
    List<String> fieldNames = schema.getFieldNames();
    List<TypeDescription> columnTypes = schema.getChildren();
    return new FileOrcStatistics(reader.getNumberOfRows(), fieldNames, statistics, columnTypes);
}

