package org.apache.flink.orc.writer;

import org.apache.flink.orc.vector.Vectorizer;
import org.apache.hadoop.hive.ql.exec.vector.VectorizedRowBatch;
import org.apache.orc.TypeDescription;
import org.apache.orc.Writer;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.IOException;

class OrcBulkWriteraddElement_VectorizedRowBatchresetFikaTest {

    @Test
    void testAddElementTriggersReset() throws IOException {
        // Create mock dependencies
        Vectorizer<String> mockVectorizer = Mockito.mock(Vectorizer.class);
        Writer mockWriter = Mockito.mock(Writer.class);

        // Create real VectorizedRowBatch with small max size to trigger reset
        TypeDescription schema = TypeDescription.createStruct()
                .addField("field1", TypeDescription.createString());
        VectorizedRowBatch rowBatch = schema.createRowBatch(2); // Small batch size

        // Configure vectorizer to return our real rowBatch
        Mockito.when(mockVectorizer.getSchema()).thenReturn(schema);

        // Create instance under test
        OrcBulkWriter<String> writer = new OrcBulkWriter<>(mockVectorizer, mockWriter);

        // Add enough elements to fill the batch and trigger reset
        writer.addElement("element1");
        writer.addElement("element2");
    }
}

