public RecordReader createRecordReader(Configuration conf, TypeDescription schema, int[] selectedFields, List<Predicate> conjunctPredicates, Path path, long splitStart, long splitLength) throws IOException {
    // open ORC file and create reader
    org.apache.hadoop.fs.Path hPath = // PATH: Test should invoke the next new Path(...) [step in execution path]
