import org.apache.hadoop.hive.ql.exec.vector.DecimalColumnVector;
import org.apache.hadoop.hive.ql.exec.vector.VectorizedRowBatch;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

public class RowDataVectorizersetColumn_HiveDecimalcreateFikaTest {

    @Test
    public void testVectorizeTriggersHiveDecimalCreate() {
        // Create a DecimalType for the test
        DecimalType decimalType = new DecimalType(10, 2);
        LogicalType[] fieldTypes = new LogicalType[]{decimalType};

        // Create the vectorizer with the schema and field types
        RowDataVectorizer vectorizer = new RowDataVectorizer("struct<col0:decimal(10,2)>", fieldTypes);

        // Create a VectorizedRowBatch with one column
        VectorizedRowBatch batch = new VectorizedRowBatch(1);
        DecimalColumnVector decimalColumnVector = new DecimalColumnVector(1);
        batch.cols = new org.apache.hadoop.hive.ql.exec.vector.ColumnVector[]{decimalColumnVector};
        batch.size = 0;

        // Create a RowData with a decimal value
        BigDecimal testDecimal = new BigDecimal("123.45");
        DecimalData decimalData = DecimalData.fromBigDecimal(testDecimal, 10, 2);
        RowData rowData = GenericRowData.of(decimalData);

        // Call the entry point method - this should trigger the call chain
        // that eventually calls HiveDecimal.create()
        vectorizer.vectorize(rowData, batch);
    }
}

