    PredicateLeaf.Type litType = getLiteralType(callExp);
    if (litType == null) {
        // unsupported literal type
        LOG.debug("Unsupported predicate [{}] cannot be pushed into OrcFileSystemFormatFactory.", callExp);
        return null;
